#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1" opener="" c
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  for c in wslview explorer.exe xdg-open open; do
    command -v "$c" >/dev/null 2>&1 && { opener=$c; break; }
  done
  if [[ -z "$opener" || ( "$opener" == xdg-open && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ) ]]; then
    warn "couldn't open a browser; visit it manually: $url"
    return 0
  fi
  # Detached: xdg-open waits on a browser it had to start (an AppImage, say) until that browser quits.
  ( "$opener" "$url" </dev/null >/dev/null 2>&1 & )
  note "if no tab opened, visit it manually"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Cairn phase 1. Run on the Beelink (an SSH session from the MacBook is fine).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

REPO=$(cd "$(dirname "$0")/../.." && pwd)
cd "$REPO"
# This wizard captures no secret. Verdicts are appended to the gate page's runs folder, which the
# agent reads when it updates the gate page.
mkdir -p ~/.config/cairn && chmod 700 ~/.config/cairn
ENV_FILE=~/.config/cairn/phase-1.env
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"
GATE=~/Developer/agent-artifacts/cairn/v2/phase-1-gate
GATE_URL=https://plans.gneiss.run/cairn/v2/phase-1-gate/
RUNS=$GATE/runs
mkdir -p "$RUNS"
VERDICTS=$RUNS/wizard.txt
PHONE=iphone-serpentine
MAC=mbp-14
# Re-run from a later stage with `ops/wizards/phase-1.sh <stage>`.
FROM_STAGE=${1:-1}
want() { (( $1 >= FROM_STAGE )) || { _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; }; }
# One line per verdict: date, stage, result, then free text.
record() { printf '%s stage=%s %s\n' "$(date -Is)" "$1" "$2" >>"$VERDICTS"; }
# Runs a judge, keeps its JSON line in the runs folder, and answers its exit code.
judge() {
  local name=$1
  shift
  local status
  set +e
  "$@" | tee "$RUNS/$name.jsonl"
  status=${PIPESTATUS[0]}
  set -e
  return "$status"
}

banner "Cairn phase 1: the phone, the MacBook and your look"

# ── 1 ─────────────────────────────────────────────────────────────────────
if want 1; then
  stage "iPhone: install the PWA"
  say "Cairn is deployed at https://code.gneiss.run, reachable only on your tailnet."
  step "On the iPhone, turn Tailscale on."
  step "In Safari, open ${BOLD}https://code.gneiss.run${RESET}. The thread list should appear."
  step "Share → Add to Home Screen → Add."
  step "Close Safari and open Cairn from its new home screen icon."
  note "If the page says \"Open Tailscale\", Tailscale is off or still connecting."
  pause "Press Enter once Cairn opened from its icon"
  record 1 "installed"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if want 2; then
  stage "iPhone: allow notifications"
  say "Web Push works only in the installed app, not in a Safari tab."
  step "In the installed Cairn: Settings (the gear at the foot of the sidebar)."
  step "Turn on ${BOLD}Notify me on this device${RESET}, then Allow when iOS asks."
  step "Lock the phone. This wizard waits for the subscription, then sends one test push."
  pause "Press Enter once you allowed it"
  if judge push node judges/push.ts --send --wait 300; then
    say ""
    if confirm "Did the notification show on the locked phone, and did tapping it open Cairn"; then
      record 2 "push=pass"
    else
      ask PUSH_NOTES "What happened instead:"
      record 2 "push=fail notes=$PUSH_NOTES"
      SKIPPED+=("stage 2: the push arrived but the phone side failed ($PUSH_NOTES)")
    fi
  else
    warn "No device answered the push (see $RUNS/push.jsonl). Check the toggle shows on, then run stage 2 again."
    record 2 "push=fail judge"
    SKIPPED+=("stage 2: push judge failed (ops/wizards/phase-1.sh 2)")
  fi
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if want 3; then
  stage "iPhone: three cold loads (ADR 0021)"
  say "Each load must reach the interactive mark in under 1,000 ms. A load that went"
  say "through a Tailscale relay (DERP) is not judged; the wizard asks for another."
  step "Checking the phone is reachable directly first:"
  tailscale ping -c 3 "$PHONE" || warn "tailscale ping found no direct path yet; loads may be flagged derp."
  since=$(date '+%Y-%m-%d %H:%M:%S')
  while true; do
    say ""
    step "Swipe Cairn away in the app switcher (force quit), then open it from its icon."
    step "Wait for the thread list, then do it again: three times in all."
    pause "Press Enter after the third load"
    status=0
    judge phone-load node judges/phone-report.ts load --unit cairn --since "$since" --device phone --runs 3 || status=$?
    if (( status == 0 )); then
      record 3 "load=pass"
      break
    fi
    if (( status == 2 )); then
      warn "Too few direct loads in the log yet (relay runs are excluded). Load it again."
      continue
    fi
    if confirm "The loads were too slow. Try another three"; then
      since=$(date '+%Y-%m-%d %H:%M:%S')
      continue
    fi
    record 3 "load=fail"
    SKIPPED+=("stage 3: phone cold loads over 1,000 ms (see $RUNS/phone-load.jsonl)")
    break
  done
  pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if want 4; then
  stage "iPhone: paste a screenshot to the model"
  say "The judge writes a page with a fresh nonce word, then follows the brain's log"
  say "until your paste reaches the model. Paste work plus send must take under 2,000 ms."
  step "On the iPhone, open ${BOLD}https://plans.gneiss.run/cairn/v2/phase-1-paste/${RESET}"
  say "    once the judge below says the page is ready, and take a screenshot."
  step "In the installed Cairn, open any thread on a model that reads images"
  say "    (Claude through the bridge is fine), paste the screenshot into the composer,"
  say "    wait for the chip, then send: ${BOLD}What word is on this image?${RESET}"
  pause "Press Enter to start the judge"
  while true; do
    status=0
    judge phone-paste node judges/paste.ts --page --wait 600 || status=$?
    if (( status == 0 )); then
      record 4 "paste=pass"
      break
    fi
    if (( status == 2 )) && confirm "No paste reached the model in ten minutes. Run the judge again"; then
      continue
    fi
    record 4 "paste=fail"
    if (( status == 2 )); then
      SKIPPED+=("stage 4: no phone paste reached the model (see $RUNS/phone-paste.jsonl)")
    else
      SKIPPED+=("stage 4: phone paste over 2,000 ms or the nonce was missing (see $RUNS/phone-paste.jsonl)")
    fi
    break
  done
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if want 5; then
  stage "MacBook: WebKit typing and load (ADR 0023)"
  if [[ -s $RUNS/webkit-typing.jsonl && -s $RUNS/webkit-load.jsonl ]]; then
    say "Claude already ran both WebKit judges on the MacBook over SSH:"
    note "$RUNS/webkit-typing.jsonl and $RUNS/webkit-load.jsonl"
    say "Nothing to do here."
  else
    say "Playwright's WebKit cannot start on the Beelink, and the MacBook was asleep"
    say "when Claude tried it over SSH. On the MacBook, in a checkout of this repo at the"
    say "deployed commit ($(git -C ~/Developer/projects/cairn-live rev-parse --short HEAD)), run:"
    say ""
    say "    ${BOLD}pnpm install --frozen-lockfile && pnpm exec playwright install webkit${RESET}"
    say "    ${BOLD}node judges/typing.ts webkit --mobile --seconds 60 | tee webkit-typing.jsonl${RESET}"
    say "    ${BOLD}node judges/load.ts --browser webkit | tee webkit-load.jsonl${RESET}"
    say ""
    note "Or just wake the MacBook and tell Claude; it runs them itself over SSH."
    if confirm "Copy the two result files from $MAC now (scp)"; then
      ask MAC_REPO "The repo's path on the MacBook (Enter for Developer/projects/cairn):"
      MAC_REPO=${MAC_REPO:-Developer/projects/cairn}
      write_env MAC_REPO "$MAC_REPO"
      scp "$MAC:$MAC_REPO/webkit-typing.jsonl" "$MAC:$MAC_REPO/webkit-load.jsonl" "$RUNS/" &&
        record 5 "webkit=copied" ||
        SKIPPED+=("stage 5: copy webkit-typing.jsonl and webkit-load.jsonl into $RUNS")
    else
      SKIPPED+=("stage 5: the WebKit runs on the MacBook")
    fi
  fi
  pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if want 6; then
  stage "Executor: sign in again, only if needed"
  say "The deployed brain imported Cairn's Executor grant, so this is usually done."
  step "In Cairn: Settings → Executor. It should read ${BOLD}Connected${RESET}."
  if confirm "Does it read Connected"; then
    note "Nothing to do."
    record 6 "executor=connected"
  else
    step "Press ${BOLD}Sign in again${RESET} in that row. Executor's consent page opens."
    step "Sign in with the Executor owner account if asked, and approve Cairn's access."
    step "You come back to Cairn's Settings; the row should now read Connected."
    pause "Press Enter once it reads Connected"
    record 6 "executor=signed-in-again"
  fi
  pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if want 7; then
  stage "Look at parity with t3code"
  say "The gate page shows Cairn beside t3code at 1440 and 390 px, with every remaining"
  say "difference marked as a declared gap or an open item for you."
  open_url "$GATE_URL"
  step "Compare the pairs at both widths, sidebar, new thread, composer, thread, diff, settings."
  step "Read the open items list: those are the differences Claude could not justify."
  say "Answer \"same\", or name what Cairn should do differently."
  if confirm "Is Cairn the same as t3code, apart from the declared gaps"; then PARITY=same; else PARITY=differs; fi
  ask PARITY_NOTES "What should change (Enter for nothing):"
  record 7 "parity=$PARITY notes=$PARITY_NOTES"
  pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if want 8; then
  stage "The daily-driver day"
  say "Use Cairn for one full working day instead of herdr: phone and desktop."
  say "Note every time you reach for a terminal, and why."
  note "You can quit now and come back with: ops/wizards/phase-1.sh 8"
  pause "Press Enter once the day is over"
  if confirm "Did Cairn carry the whole day"; then DAY=pass; else DAY=fail; fi
  ask DAY_NOTES "What made you reach for the terminal (Enter for nothing):"
  record 8 "day=$DAY notes=$DAY_NOTES"
  pause
fi

finish
say "Verdicts are in $VERDICTS. Tell Claude the wizard is done."
printf '\n'
